#ifdef NDEBUG
#error "Assertions must stay enabled for this teaching test."
#endif
#include <algorithm>
#include <cassert>
#include <iostream>
// 원작 공식이나 물리 구현이 아닌 1차원 기획 실험용 모델.
struct Fighter { int x; int damage; int stocks; };
enum class Result { Hit, RingOut, Invalid, Finished };
class Arena {
    Fighter target_;
public:
    Arena() : target_{0, 0, 2} {}
    const Fighter& state() const { return target_; }
    Result hit(int direction) {
        // 유효하지 않은 명령은 종료 상태에서도 Invalid로 분류한다.
        if (direction != -1 && direction != 1) return Result::Invalid;
        if (target_.stocks == 0) return Result::Finished;
        target_.damage = std::min(100, target_.damage + 10);
        const int distance = 1 + target_.damage / 20;
        target_.x += direction * distance;
        if (target_.x < -10 || target_.x > 10) {
            --target_.stocks;
            target_.x = 0;
            target_.damage = 0;
            return Result::RingOut;
        }
        return Result::Hit;
    }
};
int main() {
    Arena right;
    assert(right.hit(0) == Result::Invalid);
    assert(right.state().x == 0 && right.state().damage == 0);
    const int positions[] = {1, 3, 5, 8};
    for (int x : positions) {
        assert(right.hit(1) == Result::Hit);
        assert(right.state().x == x);
    }
    assert(right.hit(1) == Result::RingOut); // 8 + 3 = 11
    assert(right.state().stocks == 1 && right.state().damage == 0);
    assert(right.state().x == 0);
    for (int i = 0; i < 4; ++i) assert(right.hit(1) == Result::Hit);
    assert(right.hit(1) == Result::RingOut);
    assert(right.state().stocks == 0);
    assert(right.hit(1) == Result::Finished);
    assert(right.hit(99) == Result::Invalid);
    assert(right.state().x == 0 && right.state().damage == 0);
    Arena left;
    for (int i = 0; i < 4; ++i) assert(left.hit(-1) == Result::Hit);
    assert(left.hit(-1) == Result::RingOut);
    // 정확히 경계 +10/-10은 생존하며, 그 바깥으로 이동할 때만 이탈한다.
    const int edgePath[] = {-1, -1, 1, 1, 1, -1, 1, 1};
    for (int sign : {-1, 1}) {
        Arena edge;
        for (int direction : edgePath) assert(edge.hit(direction * sign) == Result::Hit);
        assert(edge.state().x == 10 * sign && edge.state().stocks == 2);
        assert(edge.hit(sign) == Result::RingOut);
    }
    Arena alternating;
    for (int i = 0; i < 10000; ++i) {
        assert(alternating.hit(i % 2 == 0 ? 1 : -1) == Result::Hit);
        assert(alternating.state().x >= -10 && alternating.state().x <= 10);
    }
    assert(alternating.state().damage == 100);
    assert(alternating.state().stocks == 2);
    std::cout << "prototype tests passed\n";
}
